"""Run shared workspace coverage against an explicitly chosen owned emulator, in either edition."""
from pathlib import Path
import argparse,os,subprocess
p=argparse.ArgumentParser();p.add_argument('--serial',required=True);p.add_argument('--adb-port',default='5038');p.add_argument('--lite',action='store_true');p.add_argument('--data',action='store_true');a=p.parse_args();assert not (a.lite and a.data),'Data tests are Full only';testclass='AndroidWorkspaceDataTest' if a.data else 'AndroidWorkspaceTest'
repo=Path(__file__).resolve().parents[1];root=repo/'lite' if a.lite else repo;sdk=Path(os.environ['ANDROID_HOME']);jdk=Path(os.environ['JAVA_HOME']);bt=max((sdk/'build-tools').iterdir(),key=lambda p:tuple(map(int,p.name.split('.'))));win=os.name=='nt';exe='.exe' if win else '';bat='.bat' if win else '';adb=[sdk/('platform-tools/adb'+exe),'-P',a.adb_port,'-s',a.serial]
def run(args,**kwargs):return subprocess.run(list(map(str,args)),check=True,**kwargs)
assert subprocess.check_output(list(map(str,adb+['shell','getprop','ro.kernel.qemu']))).decode().strip()=='1','Owned emulator required'
out=root/'out/workspace-tests';out.mkdir(parents=True,exist_ok=True);(out/'classes').mkdir(exist_ok=True);package='tv.vela.launcher'+('.lite' if a.lite else '');testpkg=package+'.workspace.tests'
(out/'manifest.xml').write_text('<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="'+testpkg+'"><application/><instrumentation android:name="tv.vela.launcher.'+testclass+'" android:targetPackage="'+package+'"'+('' if a.lite else ' android:targetProcesses="tv.vela.launcher:home"')+'/></manifest>',encoding='utf-8')
run([bt/('aapt2'+exe),'link','-o',out/'base.apk','-I',sdk/'platforms/android-34/android.jar','--manifest',out/'manifest.xml','--min-sdk-version','26' if a.lite else '30','--target-sdk-version','33'])
run([jdk/('bin/javac'+exe),'-encoding','UTF-8','-source','8','-target','8','-cp',os.pathsep.join([str(root/'out/classes'),str(sdk/'platforms/android-34/android.jar')]),'-d',out/'classes',repo/('tests/'+testclass+'.java')])
run([jdk/('bin/jar'+exe),'cf',out/'classes.jar','-C',out/'classes','.']);run([bt/('d8'+bat),'--min-api','26' if a.lite else '30','--lib',sdk/'platforms/android-34/android.jar','--output',out,out/'classes.jar']);run([jdk/('bin/jar'+exe),'uf',out/'base.apk','-C',out,'classes.dex']);run([bt/('zipalign'+exe),'-f','4',out/'base.apk',out/'aligned.apk']);run([bt/('apksigner'+bat),'sign','--ks',repo/'vela.keystore','--ks-pass','pass:vela-local','--out',out/'tests.apk',out/'aligned.apk'])
run(adb+['install','-r',out/'tests.apk']);text=subprocess.check_output(list(map(str,adb+['shell','am','instrument','-w',testpkg+'/tv.vela.launcher.'+testclass])),timeout=180).decode('utf-8','replace');(out/('result-data.txt' if a.data else 'result.txt')).write_text(text,encoding='utf-8');print(text.encode('ascii','backslashreplace').decode());assert 'INSTRUMENTATION_CODE: -1' in text,'Workspace tests failed'
